def transform(grid):
    h,w=len(grid),len(grid[0]); out=[[0]*w for _ in range(h)]
    seen=set(); comps=[]
    for r in range(h):
      for c in range(w):
        color=grid[r][c]
        if not color or (r,c) in seen: continue
        st=[(r,c)]; seen.add((r,c)); cells=[]
        while st:
          y,x=st.pop(); cells.append((y,x))
          for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
            if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==color:
              seen.add((yy,xx)); st.append((yy,xx))
        comps.append((color,cells))
    # Relocate each object vertically into the lower half, retaining its exact shape and x-coordinate.
    # Motifs are ordered by their source vertical location and packed into the lower rows.
    comps.sort(key=lambda z:(min(y for y,x in z[1]), min(x for y,x in z[1])))
    # Each object drops to the lowest non-overlapping position in its original columns.
    occupied=set()
    for color,cells in comps:
      cells.sort(); maxshift=h
      for y,x in cells:
        s=0
        while y+s+1<h and (y+s+1,x) not in occupied: s+=1
        maxshift=min(maxshift,s)
      for y,x in cells:
        yy=y+maxshift
        if yy<h: out[yy][x]=color; occupied.add((yy,x))
    return out
